def drive(me, enemy, arena):
    d = distance_to(enemy.x, enemy.y)
    err = bearing_to(enemy.x, enemy.y)

    # Avoid getting pinned against the arena wall when there is room to maneuver.
    if hypot(me.x, me.y) > 5.35 and d > 1.5:
        err = bearing_to(0, 0)

    steer = err / 55.0 - me.turn_rate / 150.0
    steer = max(-1.0, min(1.0, steer))

    if abs(err) > 100:
        turn = err / 35.0 - me.turn_rate / 120.0
        turn = max(-1.0, min(1.0, turn))
        return (turn, -turn)

    throttle = 0.85
    if d > 2.0:
        throttle = 1.0
    left = max(-1.0, min(1.0, throttle + steer))
    right = max(-1.0, min(1.0, throttle - steer))
    return (left, right)


