def drive(me, enemy, arena):
    if me.held or me.lifted or me.on_side:
        return (0.0, 0.0)
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    d = sqrt(dx * dx + dy * dy)
    if d < 0.02:
        return (1.0, 1.0)
    ux = dx / d
    uy = dy / d
    ef = enemy.heading * pi / 180.0
    fx = cos(ef)
    fy = sin(ef)
    front = (-ux) * fx + (-uy) * fy
    # in their front arc and close: get out of the flipper zone fast
    if front > 0.30 and d < 1.75:
        return (-1.0, -1.0)
    tx = enemy.x
    ty = enemy.y
    if front > 0.30:
        # circle them at a safe radius, looking for their thin rear
        R = 2.7
        p1x = uy
        p1y = -ux
        p2x = -uy
        p2y = ux
        c1 = (enemy.x + p1x * R) ** 2 + (enemy.y + p1y * R) ** 2
        c2 = (enemy.x + p2x * R) ** 2 + (enemy.y + p2y * R) ** 2
        mem = me.memory
        side = mem.get("side", 0)
        if side == 0:
            side = 1 if c1 <= c2 else -1
        elif side == 1 and c2 < c1 - 9.0:
            side = -1
        elif side == -1 and c1 < c2 - 9.0:
            side = 1
        mem["side"] = side
        if side == 1:
            tx = enemy.x + p1x * R
            ty = enemy.y + p1y * R
        else:
            tx = enemy.x + p2x * R
            ty = enemy.y + p2y * R
        tr = sqrt(tx * tx + ty * ty)
        if tr > 5.2:
            tx = tx * 5.2 / tr
            ty = ty * 5.2 / tr
    mr = sqrt(me.x * me.x + me.y * me.y)
    if mr > 5.2 and (enemy.x * enemy.x + enemy.y * enemy.y) < 16.0:
        tx = 0.0
        ty = 0.0
    b = bearing_to(tx, ty)
    if b > 12.0:
        return (0.25, 1.0)
    if b < -12.0:
        return (1.0, 0.25)
    return (1.0, 1.0)


