        if d < 1.5:
            tx = enemy.x + vx * 2.2 + px * 1.4
            ty = enemy.y + vy * 2.2 + py * 1.4
        else:
            tx = enemy.x + vx * 2.4 + px * 1.7
            ty = enemy.y + vy * 2.4 + py * 1.7
    elif abs(ang) > 135.0 and d < 1.7:
        tx = enemy.x
        ty = enemy.y
